package com.vib.cms.product.service;
import com.vib.cms.product.api.*;import com.vib.cms.product.repository.ProductRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ProductService {private final ProductRepository repo;public ProductService(ProductRepository repo){this.repo=repo;}public List<ProductResponse> list(){return repo.findAll();}public ProductResponse get(UUID id){return repo.find(id);}@Transactional public ProductResponse create(ProductRequest r,String actor){return repo.insert(r,actor);}@Transactional public ProductResponse update(UUID id,ProductRequest r,String actor){return repo.update(id,r,actor);}@Transactional public void archive(UUID id){repo.archive(id);}}
